    {
      "label": "A",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "悠悠悠悠将梦燃烧"
        },
        {
          "id": "C1-02",
          "zh": "以灵魂那洁白洁白的色调"
        },
        {
          "id": "C1-03",
          "zh": "只想为喜悦之火点上火苗"
        },
        {
          "id": "C1-04",
          "zh": "想象不过是些许零钱泡泡"
        },
        {
          "id": "C1-05",
          "zh": "用不冷却的话语之双手"
        },
        {
          "id": "C1-06",
          "zh": "数着那些烧不尽的所有"
        },
        {
          "id": "C1-07",
          "zh": "只想捧起就好"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "悠悠悠悠 把梦烧成灰"
        },
        {
          "id": "C1-02",
          "zh": "灵魂里那 纯白 纯白 的火色"
        },
        {
          "id": "C1-03",
          "zh": "把喜悦的火 点亮 烧旺 就这点心愿"
        },
        {
          "id": "C1-04",
          "zh": "想象是 几枚湿冷的零钱"
        },
        {
          "id": "C1-05",
          "zh": "一双手 捧起来 还热的词"
        },
        {
          "id": "C1-06",
          "zh": "数一数那些 烧不尽 的东西"
        },
        {
          "id": "C1-07",
          "zh": "我只想 捧起一捧"
        }
      ]
    }
  ]
}

